import openpyxl, os, zipfile, math, statistics
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
print('Workbook:', path)
print('Sheets:', wb.sheetnames)
print('No new sheets:', wb.sheetnames == ['Task','Data'])
print('VBA archive present:', bool(getattr(wb, 'vba_archive', None)))
with zipfile.ZipFile(path) as z:
    vba=[n for n in z.namelist() if 'vbaProject' in n or n.lower().endswith('.bin')]
print('Macro/VBA files in xlsx zip:', vba)
ws=wb['Task']
print('--- Verification rows 10-50 cols D-L ---')
def fmt(v): return '' if v is None else str(v)
for r in range(10,51):
    vals=[]
    for c in range(4,13):
        cell=ws.cell(r,c)
        vals.append(f'{cell.coordinate}={fmt(cell.value)}')
    print(' | '.join(vals))
# Formula range checks
ranges=[]
for a,b in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(a,b+1):
        for c in range(8,13):
            ranges.append((r,c))
missing=[]
for r,c in ranges:
    v=ws.cell(r,c).value
    if not (isinstance(v,str) and v.startswith('=')):
        missing.append(ws.cell(r,c).coordinate)
print('All target yellow cells contain formulas:', not missing)
if missing: print('Missing formulas:', missing)
# Check exact references for lookup formulas
lookup_bad=[]
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            col=get_column_letter(c)
            expected=f'=INDEX(Data!$H$21:$L$38, MATCH($D{r}, Data!$D$21:$D$38, 0), MATCH({col}$10, Data!$H$4:$L$4, 0))'
            if ws.cell(r,c).value != expected:
                lookup_bad.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, expected))
print('Lookup formulas reference Data series codes D21:D38, year row H4:L4, data H21:L38:', not lookup_bad)
if lookup_bad: print('Lookup mismatches:', lookup_bad[:5])
# Spot-check formulas by evaluating the intended math from Data, because openpyxl doesn't calculate formulas.
wd=wb['Data']
years=[ws.cell(10,c).value for c in range(8,13)]
series_to_row={wd.cell(r,4).value:r for r in range(21,39)}
year_to_col={wd.cell(4,c).value:c for c in range(8,13)}
print('Identified Data layout: series codes column D; years row 4 (H:L); data range H21:L38 / rows 21:38')
for col_i,year in enumerate(years, start=8):
    vals=[]; weights=[]
    for idx,r in enumerate(range(35,41)):
        cf_code=ws.cell(12+idx,4).value; op_code=ws.cell(19+idx,4).value; base_code=ws.cell(26+idx,4).value
        cf=wd.cell(series_to_row[cf_code], year_to_col[year]).value
        op=wd.cell(series_to_row[op_code], year_to_col[year]).value
        base=wd.cell(series_to_row[base_code], year_to_col[year]).value
        vals.append((cf-op)/base*100)
        weights.append(base)
    weighted=sum(v*w for v,w in zip(vals,weights))/sum(weights)
    print(f'{get_column_letter(col_i)} {year}: net buffer min={min(vals):.6f}, max={max(vals):.6f}, mean={sum(vals)/len(vals):.6f}, weighted={weighted:.6f}')
